import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import './DashboardStudent.css';

function DashboardStudent() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);

  useEffect(() => {
    const userData = localStorage.getItem('user');
    const isAuthenticated = localStorage.getItem('isAuthenticated');
    
    if (!isAuthenticated || !userData) {
      navigate("/login");
      return;
    }

    const userObj = JSON.parse(userData);
    
    if (userObj.role !== "student") {
      alert("❌ Accès réservé aux étudiants");
      navigate("/login");
      return;
    }

    setUser(userObj);
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('user');
    localStorage.removeItem('isAuthenticated');
    localStorage.removeItem('userRole');
    localStorage.removeItem('token');
    navigate("/login");
  };

  // Navigation functions
  const navigateToCourses = () => {
    navigate("/student/courses");
  };

  const navigateToGrades = () => {
    navigate("/student/grades");
  };

  const navigateToAbsences = () => {
    navigate("/student/absences");
  };

  const navigateToDocuments = () => {
    navigate("/student/documents");
  };

  if (!user) {
    return (
      <div className="loading-container">
        <div className="spinner"></div>
        <p>Chargement des données étudiant...</p>
      </div>
    );
  }

  return (
    <div className="dashboard-student">
      <header className="dashboard-header">
        <div className="header-content">
          <h1>Tableau de Bord Étudiant</h1>
          <div className="user-info">
            <span>Bienvenue, <strong>{user.nom}</strong></span>
            <div className="user-role">
              <span className="role-badge student">ÉTUDIANT</span>
              <button onClick={handleLogout} className="btn btn-secondary">
                Déconnexion
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="dashboard-main">
        <div className="welcome-section">
          <h2>Bonjour, {user.nom} 🎓</h2>
          <div className="user-details">
            <div className="info-card">
              <h3>Informations Personnelles</h3>
              <p><strong>ID:</strong> {user.id}</p>
              <p><strong>Email:</strong> {user.email}</p>
              <p><strong>Rôle:</strong> {user.role}</p>
            </div>
          </div>
        </div>

        <div className="dashboard-grid">
          <div className="dashboard-card" onClick={navigateToCourses}>
            <h3>Mes Cours</h3>
            <p>Consulter votre emploi du temps et les matières</p>
            <button className="btn btn-primary">Voir mes cours</button>
          </div>

          <div className="dashboard-card" onClick={navigateToGrades}>
            <h3>Mes Notes</h3>
            <p>Consulter vos notes et résultats académiques</p>
            <button className="btn btn-primary">Voir mes notes</button>
          </div>

          <div className="dashboard-card" onClick={navigateToAbsences}>
            <h3>Absences</h3>
            <p>Vérifier votre présence et statistiques</p>
            <button className="btn btn-primary">Voir les absences</button>
          </div>

          <div className="dashboard-card" onClick={navigateToDocuments}>
            <h3>Documents</h3>
            <p>Accéder aux ressources et supports de cours</p>
            <button className="btn btn-primary">Voir les documents</button>
          </div>
        </div>
      </main>
    </div>
  );
}

export default DashboardStudent;
